package main

import (
	"bufio"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const defaultThreshold = 15

var (
	flagFiles     = flag.Bool("files", false, "read file names from stdin one at each line")
	flagHTML      = flag.Bool("html", false, "output the results as HTML, including duplicate code fragments")
	flagPlumbing  = flag.Bool("plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flagThreshold = flag.Int("t", defaultThreshold, "minimum token sequence size as a clone")
	flagVendor    = flag.Bool("vendor", false, "check files in vendor directory")
	flagVerbose   = flag.Bool("v", false, "explain what is being done")
)

func init() {
	flag.IntVar(flagThreshold, "threshold", defaultThreshold, "minimum token sequence size as a clone")
	flag.BoolVar(flagVerbose, "verbose", false, "explain what is being done")
}

func usage() {
	fmt.Fprintf(os.Stderr, `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
  -files
    	read file names from stdin one at each line
  -html
    	output the results as HTML, including duplicate code fragments
  -plumbing
    	plumbing (easy-to-parse) output for consumption by scripts or tools
  -t, -threshold size
    	minimum token sequence size as a clone (default 15)
  -vendor
    	check files in vendor directory
  -v, -verbose
    	explain what is being done

Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`)
}

func main() {
	flag.Usage = usage
	flag.Parse()

	// Collect files
	var files []string
	if *flagFiles {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			line := scanner.Text()
			if line != "" {
				files = append(files, line)
			}
		}
	} else {
		paths := flag.Args()
		if len(paths) == 0 {
			paths = []string{"."}
		}
		for _, p := range paths {
			info, err := os.Stat(p)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			if info.IsDir() {
				goFiles, err := findGoFiles(p, *flagVendor)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
					os.Exit(1)
				}
				files = append(files, goFiles...)
			} else {
				files = append(files, p)
			}
		}
	}

	if len(files) == 0 {
		fmt.Fprintln(os.Stderr, "no files to analyze")
		return
	}

	// Tokenize all files
	if *flagVerbose {
		log.Println("Building suffix tree")
	}

	allTokens, fileInfos, err := tokenizeFiles(files)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	if *flagVerbose {
		log.Println("Searching for clones")
	}

	// Find clones using suffix array
	cloneGroups := findClones(allTokens, fileInfos, *flagThreshold)

	// Output
	if *flagHTML {
		outputHTML(cloneGroups, fileInfos)
	} else if *flagPlumbing {
		outputPlumbing(cloneGroups)
	} else {
		outputText(cloneGroups)
	}
}

func findGoFiles(dir string, includeVendor bool) ([]string, error) {
	var files []string
	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if !includeVendor && info.Name() == "vendor" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, ".go") {
			files = append(files, path)
		}
		return nil
	})
	return files, err
}

func outputText(groups []CloneGroup) {
	for _, g := range groups {
		fmt.Printf("found %d clones:\n", len(g.Clones))
		for _, c := range g.Clones {
			fmt.Printf("  %s:%d,%d\n", c.Filename, c.StartLine, c.EndLine)
		}
	}
	fmt.Printf("\nFound total %d clone groups.\n", len(groups))
}

func outputPlumbing(groups []CloneGroup) {
	for _, g := range groups {
		n := len(g.Clones)
		for i, c := range g.Clones {
			next := g.Clones[(i+1)%n]
			fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
				c.Filename, c.StartLine, c.EndLine,
				next.Filename, next.StartLine, next.EndLine)
		}
	}
}

func outputHTML(groups []CloneGroup, fileInfos []FileInfo) {
	fmt.Print(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`)
	for i, g := range groups {
		fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(g.Clones))
		for _, c := range g.Clones {
			fmt.Printf("<h2>%s:%d</h2>\n", c.Filename, c.StartLine)
			code := getSourceLines(c.Filename, c.StartLine, c.EndLine)
			fmt.Printf("<pre>%s</pre>\n", htmlEscape(code))
		}
	}
}

func htmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

func getSourceLines(filename string, start, end int) string {
	data, err := os.ReadFile(filename)
	if err != nil {
		return ""
	}
	lines := strings.Split(string(data), "\n")
	if start < 1 {
		start = 1
	}
	if end > len(lines) {
		end = len(lines)
	}
	result := strings.Join(lines[start-1:end], "\n")
	return result
}

// Clone represents a single clone instance
type Clone struct {
	Filename  string
	StartLine int
	EndLine   int
	StartTok  int // index in allTokens
	EndTok    int // index in allTokens
}

// CloneGroup is a group of clones that are identical
type CloneGroup struct {
	Clones []Clone
}

// FileInfo maps token positions back to file/line
type FileInfo struct {
	Filename  string
	StartTok  int // starting token index in the combined sequence
	EndTok    int // ending token index (exclusive)
	LineOfTok []int // line number for each token
}

func findClones(tokens []uint32, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)
	if n == 0 {
		return nil
	}

	// Build suffix array
	sa := buildSuffixArray(tokens)

	// Compute LCP array
	lcp := buildLCP(tokens, sa)

	// Find all pairs where LCP >= threshold
	// Use a stack-based approach to find groups

	type interval struct {
		lcpVal int
		left   int
		right  int
	}

	_ = interval{}

	// Find clone groups using LCP array
	// Process consecutive suffixes with LCP >= threshold

	// Build groups: for each position i in SA, if lcp[i] >= threshold,
	// then sa[i-1] and sa[i] share a common prefix of length lcp[i]

	// Use a stack-based approach to find maximal groups
	type group struct {
		minLCP int
		items  []int // positions in suffix array
	}

	// Collect all pairs with LCP >= threshold
	// Group them

	// Use union-find for grouping
	// Actually, we need to be smarter about overlapping

	// Approach: iterate over SA, group consecutive entries where LCP >= threshold
	// Each such group of consecutive SA entries forms a clone group

	// But we need to handle the case where clones might overlap each other
	// within the same file - we need to exclude self-overlapping clones

	var rawGroups [][]int // indices into SA

	i := 1
	for i <= n {
		if i < len(lcp) && lcp[i] >= threshold {
			// Start a group
			j := i - 1
			start := j
			for i < len(lcp) && lcp[i] >= threshold {
				i++
			}
			end := i - 1
			// SA[start..end] form a group with LCP >= threshold
			members := make([]int, end-start+1)
			for k := start; k <= end; k++ {
				members[k-start] = k
			}
			rawGroups = append(rawGroups, members)
		}
		i++
	}

	// Convert SA indices to clone positions
	var cloneGroups []CloneGroup

	seenGroups := make(map[string]bool)

	for _, grpIndices := range rawGroups {
		// Find the minimum LCP for this group to determine clone length
		minLCP := n
		for _, idx := range grpIndices {
			if idx < len(lcp) && lcp[idx] < minLCP {
				minLCP = lcp[idx]
			}
		}
		if minLCP > n {
			continue
		}

		// Determine the actual LCP for consecutive pairs more carefully
		// We need to find the minimal LCP within the group
		// Actually for groups, the LCP of the whole group is the minimum LCP in range

		// For each SA position, compute the clone
		var clones []Clone
		for _, idx := range grpIndices {
			pos := sa[idx]
			// Find which file this belongs to
			c := makeClone(pos, minLCP, fileInfos, tokens)
			if c != nil {
				clones = append(clones, *c)
			}
		}

		if len(clones) < 2 {
			continue
		}

		// Check for overlapping clones within the same file and remove them
		clones = removeOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		// Deduplicate groups
		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		// Sort clones within group
		sortClones(clones)

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
	}

	// Sort clone groups
	sortCloneGroups(cloneGroups)

	// Remove groups that are subsets of larger groups
	cloneGroups = filterSubgroups(cloneGroups)

	return cloneGroups
}

func makeClone(pos, length int, fileInfos []FileInfo, tokens []uint32) *Clone {
	// Find which file pos belongs to
	for _, fi := range fileInfos {
		if pos >= fi.StartTok && pos < fi.EndTok {
			startLine := fi.LineOfTok[pos-fi.StartTok]
			endPos := pos + length - 1
			if endPos >= fi.EndTok {
				return nil
			}
			endLine := fi.LineOfTok[endPos-fi.StartTok]
			return &Clone{
				Filename:  fi.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			}
		}
	}
	return nil
}

func cloneKey(c Clone) string {
	return fmt.Sprintf("%s:%d:%d", c.Filename, c.StartLine, c.EndLine)
}

func cloneGroupKey(clones []Clone) string {
	keys := make([]string, len(clones))
	for i, c := range clones {
		keys[i] = cloneKey(c)
	}
	sort.Strings(keys)
	return strings.Join(keys, "|")
}

func sortClones(clones []Clone) {
	sort.Slice(clones, func(i, j int) bool {
		if clones[i].Filename != clones[j].Filename {
			return clones[i].Filename < clones[j].Filename
		}
		if clones[i].StartLine != clones[j].StartLine {
			return clones[i].StartLine < clones[j].StartLine
		}
		return clones[i].EndLine < clones[j].EndLine
	})
}

func sortCloneGroups(groups []CloneGroup) {
	sort.Slice(groups, func(i, j int) bool {
		ci := groups[i].Clones[0]
		cj := groups[j].Clones[0]
		if ci.Filename != cj.Filename {
			return ci.Filename < cj.Filename
		}
		return ci.StartLine < cj.StartLine
	})
}

func removeOverlapping(clones []Clone) []Clone {
	// Within the same file, remove clones that overlap with another clone in the same group
	// Keep only non-overlapping ones
	// Actually, if two clones overlap within the same file, we remove the shorter one
	// or handle them specially

	// Group clones by file
	byFile := make(map[string][]Clone)
	for _, c := range clones {
		byFile[c.Filename] = append(byFile[c.Filename], c)
	}

	// For each file, remove self-overlapping clones
	var result []Clone
	removed := make(map[int]bool)

	for i := 0; i < len(clones); i++ {
		for j := i + 1; j < len(clones); j++ {
			if clones[i].Filename == clones[j].Filename {
				// Check overlap
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					// They overlap - remove the one that starts later
					if clones[i].StartTok <= clones[j].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
	}
	_ = byFile

	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
}

func filterSubgroups(groups []CloneGroup) []CloneGroup {
	// Remove groups where all clones are contained within the ranges of another group's clones
	// This is complex - for now return all groups but filter ones where both endpoints 
	// are subsets of another group

	// A group A is a subgroup of B if every clone in A is covered by some clone in B
	// by being a subrange of it

	n := len(groups)
	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if i == j {
				continue
			}
			if dominated[i] {
				break
			}
			// Check if group i is dominated by group j
			// i is dominated if every clone in i has a corresponding clone in j that contains it
			allCovered := true
			for _, ci := range groups[i].Clones {
				covered := false
				for _, cj := range groups[j].Clones {
					if ci.Filename == cj.Filename &&
						ci.StartTok >= cj.StartTok &&
						ci.EndTok <= cj.EndTok {
						covered = true
						break
					}
				}
				if !covered {
					allCovered = false
					break
				}
			}
			if allCovered {
				dominated[i] = true
			}
		}
	}

	var result []CloneGroup
	for i, g := range groups {
		if !dominated[i] {
			result = append(result, g)
		}
	}
	return result
}

// buildSuffixArray builds a suffix array for the token sequence
// Returns sorted array of starting positions
func buildSuffixArray(tokens []uint32) []int {
	n := len(tokens)
	sa := make([]int, n)
	for i := range sa {
		sa[i] = i
	}
	sort.Slice(sa, func(i, j int) bool {
		a, b := sa[i], sa[j]
		for a < n && b < n {
			if tokens[a] != tokens[b] {
				return tokens[a] < tokens[b]
			}
			a++
			b++
		}
		return a > b // longer suffix comes first? No - shorter
		// Actually: if tokens[a..] is a prefix of tokens[b..], then b comes first
		// because sa[i] < sa[j] means suffix starting at sa[i] is lexicographically smaller
	})
	return sa
}

// buildLCP builds the LCP array from the suffix array
func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens)
	lcp := make([]int, n+1)
	lcp[0] = 0
	for i := 1; i < n; i++ {
		a, b := sa[i-1], sa[i]
		l := 0
		for a+l < n && b+l < n && tokens[a+l] == tokens[b+l] {
			l++
		}
		lcp[i] = l
	}
	return lcp
}

