func filterSubgroups(groups []CloneGroup) []CloneGroup {
	// Remove groups where all clones are contained within the ranges of another group's clones
	// This is complex - for now return all groups but filter ones where both endpoints 
	// are subsets of another group

	// A group A is a subgroup of B if every clone in A is covered by some clone in B
	// by being a subrange of it

	n := len(groups)
	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if i == j {
				continue
			}
			if dominated[i] {
				break
			}
			// Check if group i is dominated by group j
			// i is dominated if every clone in i has a corresponding clone in j that contains it
			allCovered := true
			for _, ci := range groups[i].Clones {
				covered := false
				for _, cj := range groups[j].Clones {
