func findClones(tokens []uint32, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)
	if n == 0 {
		return nil
	}

	// Build suffix array
	sa := buildSuffixArray(tokens)

	// Compute LCP array
	// lcp[i] = length of longest common prefix of tokens[sa[i-1]..] and tokens[sa[i]..]
	// lcp[0] = 0 by convention
	lcp := buildLCP(tokens, sa)

