	// A clone group is a set of positions that share a common prefix of length >= threshold

	// Algorithm: scan the LCP array
	// When lcp[i] >= threshold, sa[i-1] and sa[i] are in the same group
	// We need to find all maximal groups (intervals in SA where min LCP >= threshold)

	// For each pair of adjacent SA entries with LCP >= threshold, they're clones
	// Group them transitively

	// Actually, the correct approach is:
	// For each "level" l >= threshold, find all intervals [i,j] where min(lcp[i..j]) >= l
	// These are clone groups at level l
	// We want maximal groups at each level (not subsumed by longer clones)

	// Simpler: Find all maximal intervals in SA where consecutive LCP >= threshold
	// Then process each such interval as a potential clone group

	type saGroup struct {
		start int // start index in SA
		end   int // end index in SA (inclusive)
		minLCP int // minimum LCP within the group
	}

	var saGroups []saGroup

	// Find maximal consecutive intervals where LCP >= threshold
	i := 1
	for i < n {
		if lcp[i] >= threshold {
			start := i - 1
			minL := lcp[i]
			i++
			for i < n && lcp[i] >= threshold {
				if lcp[i] < minL {
					minL = lcp[i]
				}
				i++
			}
			end := i - 1
			saGroups = append(saGroups, saGroup{start, end, minL})
		} else {
			i++
		}
	}

