// filterOverlapping removes clones that overlap within the same file
func filterOverlapping(clones []Clone) []Clone {
	// Within the same file, if two clones overlap, they shouldn't both be in the same group
	// (this can happen when the same position appears multiple times due to overlapping matches)
	// Remove the overlapping ones (keep the one with lower start position)

	removed := make([]bool, len(clones))

	for i := 0; i < len(clones); i++ {
		if removed[i] {
			continue
		}
		for j := i + 1; j < len(clones); j++ {
			if removed[j] {
				continue
			}
			if clones[i].Filename == clones[j].Filename {
				// Check overlap in token space
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					// Remove the one that starts later (or the second one if same start)
					if clones[j].StartTok >= clones[i].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
	}

	var result []Clone
	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
