// filterSubsumed removes clone groups where all clones are subranges of clones in another group
func filterSubsumed(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
