// buildLCP builds the LCP array
// lcp[i] = LCP of sa[i-1] and sa[i]
// lcp[0] = 0
func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens)
	lcp := make([]int, n)
	for i := 1; i < n; i++ {
		a, b := sa[i-1], sa[i]
		l := 0
		for a+l < n && b+l < n && tokens[a+l] == tokens[b+l] {
			l++
		}
		lcp[i] = l
	}
	return lcp
}
