				StartTok:  pos,
				EndTok:    pos + length,
			}
		}
	}
	return nil
}

// filterOverlapping removes clones that overlap within the same file
func filterOverlapping(clones []Clone) []Clone {
	// Within the same file, if two clones overlap, they shouldn't both be in the same group
	// (this can happen when the same position appears multiple times due to overlapping matches)
	// Remove the overlapping ones (keep the one with lower start position)

	removed := make([]bool, len(clones))

	for i := 0; i < len(clones); i++ {
		if removed[i] {
			continue
		}
		for j := i + 1; j < len(clones); j++ {
			if removed[j] {
				continue
			}
			if clones[i].Filename == clones[j].Filename {
				// Check overlap in token space
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					// Remove the one that starts later (or the second one if same start)
					if clones[j].StartTok >= clones[i].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
	}

	var result []Clone
	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
}

// filterSubsumed removes clone groups where all clones are subranges of clones in another group
func filterSubsumed(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
			if i == j || dominated[j] {
				continue
			}
			gj := groups[j]
			// Check if gi is subsumed by gj
			// gi is subsumed if:
			// 1. len(gi.Clones) <= len(gj.Clones) (not strictly needed but a heuristic)
			// 2. Every clone in gi has a corresponding clone in gj that contains it

			allCovered := true
			for _, ci := range gi.Clones {
				covered := false
				for _, cj := range gj.Clones {
					if ci.Filename == cj.Filename &&
						ci.StartTok >= cj.StartTok &&
						ci.EndTok <= cj.EndTok {
						covered = true
						break
					}
				}
				if !covered {
					allCovered = false
					break
				}
			}

			if allCovered {
				dominated[i] = true
				break
			}
		}
	}

	var result []CloneGroup
	for i, g := range groups {
		if !dominated[i] {
			result = append(result, g)
		}
	}
	return result
}

// buildSuffixArray builds a suffix array for the token sequence
func buildSuffixArray(tokens []uint32) []int {
	n := len(tokens)
	sa := make([]int, n)
	for i := range sa {
		sa[i] = i
	}

	// Use a simple but correct sort - O(n^2 log n) for now
	// For production, would use SA-IS or DC3
	sort.Slice(sa, func(a, b int) bool {
		pa, pb := sa[a], sa[b]
		for pa < n && pb < n {
			if tokens[pa] != tokens[pb] {
				return tokens[pa] < tokens[pb]
			}
			pa++
			pb++
		}
		// pa >= n or pb >= n
		// The shorter suffix should come first in standard SA construction
		// tokens[pa..n-1] vs tokens[pb..n-1]
		// If pa == n, suffix is empty, it's smaller
		return pa > pb
	})
	return sa
}

// buildLCP builds the LCP array
// lcp[i] = LCP of sa[i-1] and sa[i]
// lcp[0] = 0
func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens)
	lcp := make([]int, n)
	for i := 1; i < n; i++ {
		a, b := sa[i-1], sa[i]
		l := 0
		for a+l < n && b+l < n && tokens[a+l] == tokens[b+l] {
			l++
		}
		lcp[i] = l
	}
	return lcp
}
