package main

import (
	"sort"
)

// FileInfo maps token positions back to file/line
type FileInfo struct {
	Filename  string
	StartTok  int   // starting token index in combined sequence
	EndTok    int   // ending token index (exclusive)
	LineOfTok []int // line number for each token
}

func findClones(tokens []uint32, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)
	if n == 0 {
		return nil
	}

	// Build suffix array
	sa := buildSuffixArray(tokens)

	// Compute LCP array
	lcp := buildLCP(tokens, sa)

	return findClonesSimple(tokens, sa, lcp, fileInfos, threshold)
}

// findClonesSimple finds all clone groups using the suffix array and LCP array
func findClonesSimple(tokens []uint32, sa []int, lcp []int, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)

	// Build suffix tree internal nodes using LCP interval tree algorithm
	// Each internal node corresponds to a range [l, r] in SA with a minimum LCP depth

	type stNode struct {
		depth int
		left  int // left index in SA (inclusive)
		right int // right index in SA (inclusive)
	}

	var nodes []stNode

	type stackEntry struct {
		depth int
		left  int
	}

	var stStack []stackEntry

	for i := 1; i <= n; i++ {
		l := i - 1
		currentLCP := 0
		if i < n {
			currentLCP = lcp[i]
		}

		for len(stStack) > 0 && stStack[len(stStack)-1].depth > currentLCP {
			top := stStack[len(stStack)-1]
			stStack = stStack[:len(stStack)-1]

			// Node [top.left, i-1] has depth top.depth
			if top.depth >= threshold && (i-1) > top.left {
				nodes = append(nodes, stNode{
					depth: top.depth,
					left:  top.left,
					right: i - 1,
				})
			}

			if len(stStack) > 0 && stStack[len(stStack)-1].depth == currentLCP {
				l = stStack[len(stStack)-1].left
				stStack = stStack[:len(stStack)-1]
			} else {
				l = top.left
			}
		}

		if currentLCP > 0 {
			if len(stStack) == 0 || stStack[len(stStack)-1].depth < currentLCP {
				stStack = append(stStack, stackEntry{depth: currentLCP, left: l})
			}
		}
	}

	// Flush remaining stack
	for len(stStack) > 0 {
		top := stStack[len(stStack)-1]
		stStack = stStack[:len(stStack)-1]
		if top.depth >= threshold {
			nodes = append(nodes, stNode{
				depth: top.depth,
				left:  top.left,
				right: n - 1,
			})
		}
	}

	// For each node, create a clone group
	var cloneGroups []CloneGroup
	seenGroups := make(map[string]bool)

	for _, nd := range nodes {
		var clones []Clone
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			c := posToClone(pos, nd.depth, fileInfos)
			if c != nil {
				clones = append(clones, *c)
			}
		}

		if len(clones) < 2 {
			continue
		}

		// Remove overlapping clones within same file
		clones = filterOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		sortClones(clones)

		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
