package main

import (
	"sort"
)

// FileInfo maps token positions back to file/line
type FileInfo struct {
	Filename  string
	StartTok  int   // starting token index in combined sequence
	EndTok    int   // ending token index (exclusive)
	LineOfTok []int // line number for each token
}

func findClones(tokens []uint32, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)
	if n == 0 {
		return nil
	}

	sa := buildSuffixArray(tokens)
	lcp := buildLCP(tokens, sa)
	return findClonesSimple(tokens, sa, lcp, fileInfos, threshold)
}

func findClonesSimple(tokens []uint32, sa []int, lcp []int, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)

	// Build suffix tree internal nodes using LCP interval tree algorithm
	type stNode struct {
		depth int
		left  int
		right int
	}

	var nodes []stNode

	type stackEntry struct {
		depth int
		left  int
	}

	var stStack []stackEntry

	for i := 1; i <= n; i++ {
		l := i - 1
		currentLCP := 0
		if i < n {
			currentLCP = lcp[i]
		}

		for len(stStack) > 0 && stStack[len(stStack)-1].depth > currentLCP {
			top := stStack[len(stStack)-1]
			stStack = stStack[:len(stStack)-1]

			if top.depth >= threshold && (i-1) > top.left {
				nodes = append(nodes, stNode{
					depth: top.depth,
					left:  top.left,
					right: i - 1,
				})
			}

			if len(stStack) > 0 && stStack[len(stStack)-1].depth == currentLCP {
				l = stStack[len(stStack)-1].left
				stStack = stStack[:len(stStack)-1]
			} else {
				l = top.left
			}
		}

		if currentLCP > 0 {
			if len(stStack) == 0 || stStack[len(stStack)-1].depth < currentLCP {
				stStack = append(stStack, stackEntry{depth: currentLCP, left: l})
			}
		}
	}

	// Flush remaining stack
	for len(stStack) > 0 {
		top := stStack[len(stStack)-1]
		stStack = stStack[:len(stStack)-1]
		if top.depth >= threshold {
			nodes = append(nodes, stNode{
				depth: top.depth,
				left:  top.left,
				right: n - 1,
			})
		}
	}

	var cloneGroups []CloneGroup
	seenGroups := make(map[string]bool)

	for _, nd := range nodes {
		var clones []Clone
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			c := posToClone(pos, nd.depth, fileInfos)
			if c != nil {
				clones = append(clones, *c)
			}
		}

		if len(clones) < 2 {
			continue
		}

		clones = filterOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		sortClones(clones)

		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
	}

	sortCloneGroups(cloneGroups)
	cloneGroups = filterSubsumed(cloneGroups)
	sortCloneGroups(cloneGroups)

	return cloneGroups
}

func posToClone(pos, length int, fileInfos []FileInfo) *Clone {
	for _, fi := range fileInfos {
		if pos >= fi.StartTok && pos < fi.EndTok {
			// Cap the length at the file boundary
			maxLen := fi.EndTok - pos
			if length > maxLen {
				length = maxLen
			}

			startLine := fi.LineOfTok[pos-fi.StartTok]
			endPos := pos + length - 1
			endLine := fi.LineOfTok[endPos-fi.StartTok]
			return &Clone{
				Filename:  fi.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			}
		}
	}
	return nil
}

func filterOverlapping(clones []Clone) []Clone {
	removed := make([]bool, len(clones))

	for i := 0; i < len(clones); i++ {
		if removed[i] {
			continue
		}
		for j := i + 1; j < len(clones); j++ {
			if removed[j] {
				continue
			}
			if clones[i].Filename == clones[j].Filename {
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					if clones[j].StartTok >= clones[i].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
	}

	var result []Clone
	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
}

// filterSubsumed removes clone groups that are subsumed by other groups.
// A group G is subsumed if:
// 1. (Injection-based): All G-clones are sub-ranges of H-clones with injective mapping
// 2. (Adjacency-based): All G-clones are within H-clones (non-injection), and
//    within each H-clone, the G-clones are directly adjacent (no gaps between them)
func filterSubsumed(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
			if i == j || dominated[j] {
				continue
			}
			gj := groups[j]

			// Check injection-based subsumption: gi is subsumed by gj
			// (gi's clones fit injectively within gj's clones)
			if len(gi.Clones) <= len(gj.Clones) {
				if isSubsumedByInjection(gi, gj) {
					dominated[i] = true
					break
				}
			}

			// Check adjacency-based subsumption: gi is subsumed by gj
			// (all gi-clones are within gj-clones, and within each gj-clone
			// the gi-clones are directly adjacent with no gaps)
			if !dominated[i] && isSubsumedByAdjacency(gi, gj) {
				dominated[i] = true
				break
			}
		}
	}

	var result []CloneGroup
	for i, g := range groups {
		if !dominated[i] {
			result = append(result, g)
		}
	}
	return result
}

// isSubsumedByInjection checks if gi is injectively subsumed by gj
// (there's an injective mapping from gi to gj where each gi clone ⊆ corresponding gj clone)
func isSubsumedByInjection(gi, gj CloneGroup) bool {
	if len(gi.Clones) > len(gj.Clones) {
		return false
	}

	used := make([]bool, len(gj.Clones))
	return findInjection(gi.Clones, gj.Clones, used, 0)
}

func findInjection(giClones, gjClones []Clone, used []bool, idx int) bool {
	if idx == len(giClones) {
		return true
	}
	ci := giClones[idx]
	for k, cj := range gjClones {
		if used[k] {
			continue
		}
		if ci.Filename == cj.Filename &&
			ci.StartTok >= cj.StartTok &&
			ci.EndTok <= cj.EndTok {
			used[k] = true
			if findInjection(giClones, gjClones, used, idx+1) {
				return true
			}
			used[k] = false
		}
	}
	return false
}

// isSubsumedByAdjacency checks if gi is subsumed by gj via adjacency rule:
// All gi-clones are within gj-clones, and within each gj-clone,
// the gi-clones are directly adjacent (no gaps between consecutive gi-clones)
func isSubsumedByAdjacency(gi, gj CloneGroup) bool {
	if len(gi.Clones) <= len(gj.Clones) {
		return false // Adjacency rule only applies when |G| > |H|
	}

	// Check that all gi-clones are within some gj-clone
	// Group gi-clones by which gj-clone they belong to
	gjCloneForGi := make(map[int]int) // gi-clone index → gj-clone index

	for giIdx, ci := range gi.Clones {
		found := false
		for gjIdx, cj := range gj.Clones {
			if ci.Filename == cj.Filename &&
				ci.StartTok >= cj.StartTok &&
				ci.EndTok <= cj.EndTok {
				gjCloneForGi[giIdx] = gjIdx
				found = true
				break
			}
		}
		if !found {
			return false // some gi-clone is not within any gj-clone
		}
	}

	// For each gj-clone, check that the gi-clones within it are adjacent
	// Group gi-clones by their gj-clone
	gjGroups := make(map[int][]int) // gj-clone index → list of gi-clone indices
	for giIdx, gjIdx := range gjCloneForGi {
		gjGroups[gjIdx] = append(gjGroups[gjIdx], giIdx)
	}

	for _, giIndices := range gjGroups {
		if len(giIndices) < 2 {
			continue // Only one gi-clone in this gj-clone, no adjacency check needed
		}

		// Sort gi-clones by start position
		sort.Slice(giIndices, func(a, b int) bool {
			return gi.Clones[giIndices[a]].StartTok < gi.Clones[giIndices[b]].StartTok
		})

		// Check adjacency: each clone ends exactly where the next starts
		for k := 0; k < len(giIndices)-1; k++ {
			c1 := gi.Clones[giIndices[k]]
			c2 := gi.Clones[giIndices[k+1]]
			if c1.EndTok != c2.StartTok {
				return false // gap between consecutive gi-clones
			}
		}
	}

	return true
}

func buildSuffixArray(tokens []uint32) []int {
	n := len(tokens)
	sa := make([]int, n)
