		var clones []Clone
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			c := posToClone(pos, nd.depth, fileInfos)
			if c != nil {
				clones = append(clones, *c)
			}
		}

		if len(clones) < 2 {
			continue
		}

		clones = filterOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		sortClones(clones)

		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
	}

	sortCloneGroups(cloneGroups)

	// Apply filtering in two passes:
	// Pass 1: Injection-based filter (smaller groups subsumed by larger groups)
	cloneGroups = filterByInjection(cloneGroups)
	sortCloneGroups(cloneGroups)

	// Pass 2: Adjacency-based filter (remove groups where clones are adjacent within larger groups)
	cloneGroups = filterByAdjacency(cloneGroups)
	sortCloneGroups(cloneGroups)

