func posToClone(pos, length int, fileInfos []FileInfo) *Clone {
	for _, fi := range fileInfos {
		if pos >= fi.StartTok && pos < fi.EndTok {
			maxLen := fi.EndTok - pos
			if length > maxLen {
				length = maxLen
			}

			startLine := fi.LineOfTok[pos-fi.StartTok]
			endPos := pos + length - 1
			endLine := fi.LineOfTok[endPos-fi.StartTok]
			return &Clone{
				Filename:  fi.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			}
		}
	}
	return nil
}

func filterOverlapping(clones []Clone) []Clone {
	removed := make([]bool, len(clones))

	for i := 0; i < len(clones); i++ {
		if removed[i] {
			continue
		}
		for j := i + 1; j < len(clones); j++ {
			if removed[j] {
				continue
			}
			if clones[i].Filename == clones[j].Filename {
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					if clones[j].StartTok >= clones[i].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
	}

	var result []Clone
	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
}

// filterByInjection removes groups that are injectively subsumed by other groups.
// A group G is subsumed if all G-clones fit injectively within H-clones.
func filterByInjection(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
			if i == j || dominated[j] {
				continue
			}
			gj := groups[j]

			if len(gi.Clones) <= len(gj.Clones) {
				if isSubsumedByInjection(gi, gj) {
					dominated[i] = true
					break
				}
			}
		}
	}

	var result []CloneGroup
	for i, g := range groups {
		if !dominated[i] {
			result = append(result, g)
		}
	}
	return result
}

// filterByAdjacency removes groups where clones are adjacent within larger groups.
// Specifically, removes G if:
// - All G-clones are within some H-clone (non-injection)
// - |G| > |H| (G has more clones than H)
// - Within each H-clone, the G-clones are directly adjacent (no gaps)
func filterByAdjacency(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
			if i == j || dominated[j] {
				continue
			}
			gj := groups[j]

			if len(gi.Clones) > len(gj.Clones) {
				if isSubsumedByAdjacency(gi, gj) {
					dominated[i] = true
					break
				}
			}
		}
	}

	var result []CloneGroup
	for i, g := range groups {
		if !dominated[i] {
			result = append(result, g)
		}
	}
	return result
}

// isSubsumedByInjection checks if gi is injectively subsumed by gj
func isSubsumedByInjection(gi, gj CloneGroup) bool {
	if len(gi.Clones) > len(gj.Clones) {
		return false
	}

	used := make([]bool, len(gj.Clones))
	return findInjection(gi.Clones, gj.Clones, used, 0)
}

func findInjection(giClones, gjClones []Clone, used []bool, idx int) bool {
	if idx == len(giClones) {
		return true
	}
	ci := giClones[idx]
	for k, cj := range gjClones {
		if used[k] {
			continue
		}
		if ci.Filename == cj.Filename &&
			ci.StartTok >= cj.StartTok &&
			ci.EndTok <= cj.EndTok {
			used[k] = true
			if findInjection(giClones, gjClones, used, idx+1) {
				return true
			}
			used[k] = false
		}
	}
	return false
}

// isSubsumedByAdjacency checks if gi is subsumed by gj via adjacency rule
func isSubsumedByAdjacency(gi, gj CloneGroup) bool {
	if len(gi.Clones) <= len(gj.Clones) {
		return false
	}

	// Check that all gi-clones are within some gj-clone
	gjCloneForGi := make(map[int]int)

	for giIdx, ci := range gi.Clones {
		found := false
		for gjIdx, cj := range gj.Clones {
			if ci.Filename == cj.Filename &&
				ci.StartTok >= cj.StartTok &&
				ci.EndTok <= cj.EndTok {
				gjCloneForGi[giIdx] = gjIdx
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}

	// For each gj-clone, check that the gi-clones within it are adjacent
	gjGroups := make(map[int][]int)
	for giIdx, gjIdx := range gjCloneForGi {
		gjGroups[gjIdx] = append(gjGroups[gjIdx], giIdx)
	}

	for _, giIndices := range gjGroups {
		if len(giIndices) < 2 {
			continue
		}

		sort.Slice(giIndices, func(a, b int) bool {
			return gi.Clones[giIndices[a]].StartTok < gi.Clones[giIndices[b]].StartTok
		})

		for k := 0; k < len(giIndices)-1; k++ {
			c1 := gi.Clones[giIndices[k]]
			c2 := gi.Clones[giIndices[k+1]]
			if c1.EndTok != c2.StartTok {
				return false
			}
		}
	}

	return true
}

func buildSuffixArray(tokens []uint32) []int {
	n := len(tokens)
	sa := make([]int, n)
	for i := range sa {
		sa[i] = i
	}

	sort.Slice(sa, func(a, b int) bool {
		pa, pb := sa[a], sa[b]
		for pa < n && pb < n {
			if tokens[pa] != tokens[pb] {
				return tokens[pa] < tokens[pb]
			}
			pa++
			pb++
		}
		return pa > pb
	})
	return sa
}

func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens)
	lcp := make([]int, n)
	for i := 1; i < n; i++ {
		a, b := sa[i-1], sa[i]
		l := 0
		for a+l < n && b+l < n && tokens[a+l] == tokens[b+l] {
			l++
		}
		lcp[i] = l
	}
	return lcp
}
