package main

import (
	"sort"
)

type FileInfo struct {
	Filename  string
	StartTok  int
	EndTok    int
	LineOfTok []int
}

func findClones(tokens []uint32, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)
	if n == 0 {
		return nil
	}
	sa := buildSuffixArray(tokens)
	lcp := buildLCP(tokens, sa)
	return findClonesSimple(tokens, sa, lcp, fileInfos, threshold)
}

func findClonesSimple(tokens []uint32, sa []int, lcp []int, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)

	type stNode struct {
		depth int
		left  int
		right int
	}
	var nodes []stNode

	type stackEntry struct {
		depth int
		left  int
	}
	var stStack []stackEntry

	for i := 1; i <= n; i++ {
		l := i - 1
		currentLCP := 0
		if i < n {
			currentLCP = lcp[i]
		}

		for len(stStack) > 0 && stStack[len(stStack)-1].depth > currentLCP {
			top := stStack[len(stStack)-1]
			stStack = stStack[:len(stStack)-1]

			if top.depth >= threshold && (i-1) > top.left {
				nodes = append(nodes, stNode{
					depth: top.depth,
					left:  top.left,
					right: i - 1,
				})
			}

			if len(stStack) > 0 && stStack[len(stStack)-1].depth == currentLCP {
				l = stStack[len(stStack)-1].left
				stStack = stStack[:len(stStack)-1]
			} else {
				l = top.left
			}
		}

		if currentLCP > 0 {
			if len(stStack) == 0 || stStack[len(stStack)-1].depth < currentLCP {
				stStack = append(stStack, stackEntry{depth: currentLCP, left: l})
			}
		}
	}

	for len(stStack) > 0 {
		top := stStack[len(stStack)-1]
		stStack = stStack[:len(stStack)-1]
		if top.depth >= threshold {
			nodes = append(nodes, stNode{
				depth: top.depth,
				left:  top.left,
				right: n - 1,
			})
		}
	}

	var cloneGroups []CloneGroup
	seenGroups := make(map[string]bool)

	for _, nd := range nodes {
		var clones []Clone
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			c := posToClone(pos, nd.depth, fileInfos)
			if c != nil {
				clones = append(clones, *c)
			}
		}

		if len(clones) < 2 {
			continue
		}

		clones = filterOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		sortClones(clones)

		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
	}

	sortCloneGroups(cloneGroups)
	cloneGroups = filterSubsumed(cloneGroups)
	sortCloneGroups(cloneGroups)

	return cloneGroups
}

func posToClone(pos, length int, fileInfos []FileInfo) *Clone {
	for _, fi := range fileInfos {
		if pos >= fi.StartTok && pos < fi.EndTok {
			maxLen := fi.EndTok - pos
			if length > maxLen {
				length = maxLen
			}
			startLine := fi.LineOfTok[pos-fi.StartTok]
			endPos := pos + length - 1
			endLine := fi.LineOfTok[endPos-fi.StartTok]
			return &Clone{
				Filename:  fi.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			}
		}
	}
	return nil
}

func filterOverlapping(clones []Clone) []Clone {
	removed := make([]bool, len(clones))

	for i := 0; i < len(clones); i++ {
		if removed[i] {
			continue
		}
		for j := i + 1; j < len(clones); j++ {
			if removed[j] {
				continue
			}
			if clones[i].Filename == clones[j].Filename {
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					if clones[j].StartTok >= clones[i].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
