func sortSA(sa []int, cmp func(a, b int) int) {
	// Simple insertion sort for small arrays, otherwise use quicksort
	n := len(sa)
	if n < 20 {
		for i := 1; i < n; i++ {
			key := sa[i]
			j := i - 1
			for j >= 0 && cmp(sa[j], key) > 0 {
				sa[j+1] = sa[j]
				j--
			}
			sa[j+1] = key
		}
