func sortSAQuick(sa []int, cmp func(a, b int) int, lo, hi, depth int) {
	if hi-lo < 20 {
		for i := lo + 1; i <= hi; i++ {
			key := sa[i]
			j := i - 1
			for j >= lo && cmp(sa[j], key) > 0 {
				sa[j+1] = sa[j]
				j--
			}
			sa[j+1] = key
		}
		return
	}
	// Choose pivot (median of three)
	mid := lo + (hi-lo)/2
	if cmp(sa[lo], sa[mid]) > 0 {
		sa[lo], sa[mid] = sa[mid], sa[lo]
	}
	if cmp(sa[lo], sa[hi]) > 0 {
		sa[lo], sa[hi] = sa[hi], sa[lo]
	}
	if cmp(sa[mid], sa[hi]) > 0 {
		sa[mid], sa[hi] = sa[hi], sa[mid]
	}
	pivot := sa[mid]
	sa[mid], sa[hi-1] = sa[hi-1], sa[mid]

	i, j := lo, hi-1
	for {
		i++
		for cmp(sa[i], pivot) < 0 {
			i++
		}
		j--
		for cmp(pivot, sa[j]) < 0 {
			j--
		}
		if i >= j {
			break
		}
		sa[i], sa[j] = sa[j], sa[i]
	}
	sa[i], sa[hi-1] = sa[hi-1], sa[i]

