	// Initial rank assignment based on first character
	sa := make([]int, n)
	rank := make([]int, n)
	tmp := make([]int, n)

	for i := 0; i < n; i++ {
		sa[i] = i
		rank[i] = int(tokens[i])
	}

	// Sort by first character
	countSort(sa, rank, n)

	// Update ranks based on sorted order
	assignRanks(sa, rank, tmp, n, func(i, j int) bool {
		return rank[sa[i]] != rank[sa[j]]
	})

	// Prefix doubling
	for gap := 1; gap < n; gap *= 2 {
		// Create comparison function using ranks of (i, i+gap) pairs
		cmp := func(a, b int) int {
			r1a := rank[a]
			r1b := rank[b]
			if r1a != r1b {
				if r1a < r1b {
					return -1
				}
				return 1
			}
			r2a := -1
			r2b := -1
			if a+gap < n {
				r2a = rank[a+gap]
			}
			if b+gap < n {
				r2b = rank[b+gap]
			}
			if r2a < r2b {
				return -1
			}
			if r2a > r2b {
				return 1
			}
			return 0
		}

		// Sort SA based on rank pairs
		sortSA(sa, cmp)

		// Assign new ranks
		if assignRanks(sa, rank, tmp, n, func(i, j int) bool {
			return cmp(sa[i], sa[j]) != 0
		}) == n {
			break // All ranks are unique, done
		}
	}

	return sa
}

// sortSA sorts suffix array using the given comparison function
func sortSA(sa []int, cmp func(a, b int) int) {
	// Simple insertion sort for small arrays, otherwise use quicksort
	n := len(sa)
	if n < 20 {
		for i := 1; i < n; i++ {
			key := sa[i]
			j := i - 1
			for j >= 0 && cmp(sa[j], key) > 0 {
				sa[j+1] = sa[j]
				j--
			}
			sa[j+1] = key
		}
		return
	}
	// Use std sort (introsort)
	sortSAQuick(sa, cmp, 0, n-1, 0)
}

func sortSAQuick(sa []int, cmp func(a, b int) int, lo, hi, depth int) {
	if hi-lo < 20 {
		for i := lo + 1; i <= hi; i++ {
			key := sa[i]
			j := i - 1
			for j >= lo && cmp(sa[j], key) > 0 {
				sa[j+1] = sa[j]
				j--
			}
			sa[j+1] = key
		}
		return
	}
	// Choose pivot (median of three)
	mid := lo + (hi-lo)/2
	if cmp(sa[lo], sa[mid]) > 0 {
		sa[lo], sa[mid] = sa[mid], sa[lo]
	}
	if cmp(sa[lo], sa[hi]) > 0 {
		sa[lo], sa[hi] = sa[hi], sa[lo]
	}
	if cmp(sa[mid], sa[hi]) > 0 {
		sa[mid], sa[hi] = sa[hi], sa[mid]
	}
	pivot := sa[mid]
	sa[mid], sa[hi-1] = sa[hi-1], sa[mid]

	i, j := lo, hi-1
	for {
		i++
		for cmp(sa[i], pivot) < 0 {
			i++
		}
		j--
		for cmp(pivot, sa[j]) < 0 {
			j--
		}
		if i >= j {
			break
		}
		sa[i], sa[j] = sa[j], sa[i]
	}
	sa[i], sa[hi-1] = sa[hi-1], sa[i]

	sortSAQuick(sa, cmp, lo, i-1, depth+1)
	sortSAQuick(sa, cmp, i+1, hi, depth+1)
}

// countSort does an initial sort based on rank values
func countSort(sa, rank []int, n int) {
	// Find max rank
	maxRank := 0
	for _, r := range rank {
		if r > maxRank {
			maxRank = r
		}
	}

	// Count sort
	count := make([]int, maxRank+2)
	for _, r := range rank {
		count[r+1]++
	}
	for i := 1; i < len(count); i++ {
		count[i] += count[i-1]
	}
	for i := 0; i < n; i++ {
		sa[count[rank[i]]] = i
		count[rank[i]]++
	}
}

// assignRanks assigns new rank values based on sorted order
// Returns the number of unique ranks
func assignRanks(sa []int, rank, tmp []int, n int, diff func(i, j int) bool) int {
	unique := 1
	tmp[sa[0]] = 0
	for i := 1; i < n; i++ {
		if diff(i, i-1) {
			unique++
		}
		tmp[sa[i]] = unique - 1
	}
	copy(rank, tmp)
	return unique
}

// buildLCP builds the LCP array using Kasai's O(n) algorithm
func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens)
	lcp := make([]int, n)

	// Build inverse SA (rank array)
	rank := make([]int, n)
	for i, s := range sa {
		rank[s] = i
	}

	h := 0
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]
			for i+h < n && j+h < n && tokens[i+h] == tokens[j+h] {
				h++
			}
			lcp[rank[i]] = h
			if h > 0 {
				h--
			}
		}
	}
	return lcp
}
