# Let me check the LCP and node processing:

cat > /tmp/bench_all.go << 'EOF'
package main

import (
	"fmt"
	"time"
	"sort"
	"os"
	"go/scanner"
	"go/token"
)

func tokenizeFile(fn string) ([]uint32, []int) {
	data, _ := os.ReadFile(fn)
	fset := token.NewFileSet()
	file := fset.AddFile("", fset.Base(), len(data))
	var s scanner.Scanner
	s.Init(file, data, nil, 0)
	var toks []uint32; var lines []int
	for {
		pos, tok, _ := s.Scan()
		if tok == token.EOF { break }
		if tok == token.COMMENT { continue }
		toks = append(toks, uint32(tok))
		lines = append(lines, fset.Position(pos).Line)
	}
	return toks, lines
}

func buildSA(tokens []uint32) []int {
	n := len(tokens)
	sa := make([]int, n)
	rank := make([]int, n)
	for i := range sa { sa[i] = i; rank[i] = int(tokens[i]) }
	for gap := 1; gap < n; gap *= 2 {
		r := make([]int, n); copy(r, rank)
		sort.Slice(sa, func(a, b int) bool {
			pi, pj := sa[a], sa[b]
			if r[pi] != r[pj] { return r[pi] < r[pj] }
			ri, rj := -1, -1
			if pi+gap < n { ri = r[pi+gap] }
			if pj+gap < n { rj = r[pj+gap] }
			return ri < rj
		})
		rank[sa[0]] = 0
		for i := 1; i < n; i++ {
			if r[sa[i]] != r[sa[i-1]] || (sa[i]+gap < n && sa[i-1]+gap < n && r[sa[i]+gap] != r[sa[i-1]+gap]) {
				rank[sa[i]] = rank[sa[i-1]] + 1
			} else {
				rank[sa[i]] = rank[sa[i-1]]
			}
		}
		if rank[sa[n-1]] == n-1 { break }
	}
	return sa
}

func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens); lcp := make([]int, n)
	rank := make([]int, n); for i, s := range sa { rank[s] = i }
	h := 0
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]; for i+h < n && j+h < n && tokens[i+h] == tokens[j+h] { h++ }
			lcp[rank[i]] = h; if h > 0 { h-- }
		}
	}
	return lcp
}

type FileInfo struct { Filename string; StartTok, EndTok int; LineOfTok []int }

func main() {
	files := getFiles(200)
	var allTokens []uint32; var fis []FileInfo
	for _, f := range files {
		toks, lines := tokenizeFile(f)
		startIdx := len(allTokens)
		allTokens = append(allTokens, toks...); allTokens = append(allTokens, 0)
		fis = append(fis, FileInfo{f, startIdx, startIdx+len(toks), lines})
	}
	fmt.Printf("Total tokens: %d\n", len(allTokens))

	t0 := time.Now()
	sa := buildSA(allTokens); t1 := time.Now()
	fmt.Printf("SA: %v\n", t1.Sub(t0))

	lcp := buildLCP(allTokens, sa); t2 := time.Now()
	fmt.Printf("LCP: %v\n", t2.Sub(t1))

	// Count LCP interval tree nodes
	threshold := 200; n := len(allTokens)
	nodeCount := 0; seenGroups := make(map[string]bool)

	type stNode struct { depth, left, right int }
	var nodes []stNode; type stackEntry struct { depth, left int }; var stStack []stackEntry
	for i := 1; i <= n; i++ {
		l := i - 1; cur := 0; if i < n { cur = lcp[i] }
		for len(stStack) > 0 && stStack[len(stStack)-1].depth > cur {
			top := stStack[len(stStack)-1]; stStack = stStack[:len(stStack)-1]
			if top.depth >= threshold && (i-1) > top.left { nodes = append(nodes, stNode{top.depth, top.left, i-1}); nodeCount++ }
			if len(stStack) > 0 && stStack[len(stStack)-1].depth == cur { l = stStack[len(stStack)-1].left; stStack = stStack[:len(stStack)-1] } else { l = top.left }
		}
		if cur > 0 { if len(stStack) == 0 || stStack[len(stStack)-1].depth < cur { stStack = append(stStack, stackEntry{cur, l}) } }
	}
	for len(stStack) > 0 {
		top := stStack[len(stStack)-1]; stStack = stStack[:len(stStack)-1]
		if top.depth >= threshold { nodes = append(nodes, stNode{top.depth, top.left, n-1}); nodeCount++ }
	}
	t3 := time.Now()
	fmt.Printf("LCP tree nodes: %d (time: %v)\n", nodeCount, t3.Sub(t2))

	// Process nodes into clone groups
	groupCount := 0
	for _, nd := range nodes {
		var keys []string
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			for _, fi := range fis {
				if pos >= fi.StartTok && pos < fi.EndTok {
					maxLen := fi.EndTok - pos
					if nd.depth < maxLen { maxLen = nd.depth }
					sl := fi.LineOfTok[pos-fi.StartTok]; el := fi.LineOfTok[pos+maxLen-1-fi.StartTok]
					keys = append(keys, fmt.Sprintf("%s:%d:%d", fi.Filename, sl, el))
				}
			}
		}
		if len(keys) < 2 { continue }
		sort.Strings(keys)
		gkey := fmt.Sprintf("%v", keys)
		if !seenGroups[gkey] { seenGroups[gkey] = true; groupCount++ }
	}
	t4 := time.Now()
	fmt.Printf("Clone groups: %d (time: %v)\n", groupCount, t4.Sub(t3))
	fmt.Printf("Total: %v\n", t4.Sub(t0))
}

func getFiles(n int) []string {
	var files []string
	walkDir("/usr/local/go/src/cmd", &files, n)
	return files
}

func walkDir(dir string, files *[]string, limit int) {
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
