			if len(stStack) == 0 || stStack[len(stStack)-1].depth < currentLCP {
				stStack = append(stStack, stackEntry{depth: currentLCP, left: l})
			}
		}
	}

	for len(stStack) > 0 {
		top := stStack[len(stStack)-1]
		stStack = stStack[:len(stStack)-1]
		if top.depth >= threshold {
			nodes = append(nodes, stNode{
				depth: top.depth,
				left:  top.left,
				right: n - 1,
			})
		}
	}

	// Process nodes into clone groups
	var cloneGroups []CloneGroup
	seenGroups := make(map[string]bool)

	for _, nd := range nodes {
		var clones []Clone
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			fi := posToFI[pos]
			if fi < 0 {
				continue
			}
			info := fileInfos[fi]
			maxLen := info.EndTok - pos
			length := nd.depth
			if length > maxLen {
				length = maxLen
			}

			startLine := info.LineOfTok[pos-info.StartTok]
			endPos := pos + length - 1
			endLine := info.LineOfTok[endPos-info.StartTok]
			clones = append(clones, Clone{
				Filename:  info.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			})
		}

		if len(clones) < 2 {
			continue
		}

		clones = filterOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		sortClones(clones)

		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
	}

	sortCloneGroups(cloneGroups)
	cloneGroups = filterSubsumed(cloneGroups)
	sortCloneGroups(cloneGroups)

	return cloneGroups
}

func filterOverlapping(clones []Clone) []Clone {
	removed := make([]bool, len(clones))

	for i := 0; i < len(clones); i++ {
		if removed[i] {
			continue
		}
		for j := i + 1; j < len(clones); j++ {
			if removed[j] {
				continue
			}
			if clones[i].Filename == clones[j].Filename {
				if clones[i].StartTok < clones[j].EndTok && clones[j].StartTok < clones[i].EndTok {
					if clones[j].StartTok >= clones[i].StartTok {
						removed[j] = true
					} else {
						removed[i] = true
					}
				}
			}
		}
	}

	var result []Clone
	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
}

func filterSubsumed(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
			if i == j || dominated[j] {
				continue
			}
			gj := groups[j]

			if len(gi.Clones) <= len(gj.Clones) {
				if isSubsumedByInjection(gi, gj) {
					dominated[i] = true
					break
				}
			}
		}
	}

	var result []CloneGroup
	for i, g := range groups {
		if !dominated[i] {
			result = append(result, g)
		}
	}
	return result
}

func isSubsumedByInjection(gi, gj CloneGroup) bool {
	if len(gi.Clones) > len(gj.Clones) {
		return false
	}

	used := make([]bool, len(gj.Clones))
	return findInjection(gi.Clones, gj.Clones, used, 0)
}

func findInjection(giClones, gjClones []Clone, used []bool, idx int) bool {
	if idx == len(giClones) {
		return true
	}
	ci := giClones[idx]
	for k, cj := range gjClones {
		if used[k] {
			continue
		}
		if ci.Filename == cj.Filename &&
			ci.StartTok >= cj.StartTok &&
			ci.EndTok <= cj.EndTok {
			used[k] = true
			if findInjection(giClones, gjClones, used, idx+1) {
				return true
			}
			used[k] = false
		}
	}
	return false
}

// cloneGroupKey creates a string key for a clone group
func cloneGroupKey(clones []Clone) string {
	keys := make([]string, len(clones))
	for i, c := range clones {
		keys[i] = fmt.Sprintf("%s:%d:%d", c.Filename, c.StartLine, c.EndLine)
	}
	sort.Strings(keys)
	return strings.Join(keys, "|")
}

// sortClones sorts clones by filename and start line
func sortClones(clones []Clone) {
	sort.Slice(clones, func(i, j int) bool {
		if clones[i].Filename != clones[j].Filename {
			return clones[i].Filename < clones[j].Filename
		}
		if clones[i].StartLine != clones[j].StartLine {
			return clones[i].StartLine < clones[j].StartLine
		}
		return clones[i].EndLine < clones[j].EndLine
	})
}

// sortCloneGroups sorts clone groups by first clone's filename and line
func sortCloneGroups(groups []CloneGroup) {
	sort.Slice(groups, func(i, j int) bool {
		ci := groups[i].Clones[0]
		cj := groups[j].Clones[0]
		if ci.Filename != cj.Filename {
			return ci.Filename < cj.Filename
		}
		return ci.StartLine < cj.StartLine
	})
}
