			pi, pj := sa[a], sa[b]
			if r[pi] != r[pj] { return r[pi] < r[pj] }
			ri, rj := -1, -1
			if pi+gap < n { ri = r[pi+gap] }
			if pj+gap < n { rj = r[pj+gap] }
			return ri < rj
		})
		rank[sa[0]] = 0
		for i := 1; i < n; i++ {
			if r[sa[i]] != r[sa[i-1]] || (sa[i]+gap < n && sa[i-1]+gap < n && r[sa[i]+gap] != r[sa[i-1]+gap]) {
				rank[sa[i]] = rank[sa[i-1]] + 1
			} else {
				rank[sa[i]] = rank[sa[i-1]]
			}
		}
		if rank[sa[n-1]] == n-1 { break }
	}
	return sa
}

func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens); lcp := make([]int, n)
	rank := make([]int, n); for i, s := range sa { rank[s] = i }
	h := 0
	for i := 0; i < n; i++ {
		if rank[i] > 0 {
			j := sa[rank[i]-1]
			for i+h < n && j+h < n && tokens[i+h] == tokens[j+h] { h++ }
			lcp[rank[i]] = h; if h > 0 { h-- }
		}
	}
	return lcp
}

