	if idx == len(gi) { return true }
	ci := gi[idx]
	for k, cj := range gj {
		if used[k] { continue }
		if ci.Filename == cj.Filename && ci.StartTok >= cj.StartTok && ci.EndTok <= cj.EndTok {
			used[k] = true
			if checkInjection(gi, gj, used, idx+1) { return true }
			used[k] = false
		}
	}
	return false
}

type Clone struct { Filename string; StartLine, EndLine, StartTok, EndTok int }

func checkInjectionC(gi, gj []Clone, used []bool, idx int) bool {
	if idx == len(gi) { return true }
	ci := gi[idx]
	for k, cj := range gj {
		if used[k] { continue }
		if ci.Filename == cj.Filename && ci.StartTok >= cj.StartTok && ci.EndTok <= cj.EndTok {
			used[k] = true
			if checkInjectionC(gi, gj, used, idx+1) { return true }
			used[k] = false
		}
	}
