func getFiles(n int) []string {
	var files []string
	walkDir("/usr/local/go/src/cmd", &files, n)
	return files
}

func walkDir(dir string, files *[]string, limit int) {
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		if len(*files) >= limit { return }
		path := dir + "/" + e.Name()
		if e.IsDir() { walkDir(path, files, limit) } else if len(e.Name()) > 3 && e.Name()[len(e.Name())-3:] == ".go" { *files = append(*files, path) }
	}
}
