	"time"
	"sort"
	"os"
	"go/scanner"
	"go/token"
)

func abstract(tok token.Token) uint32 {
	switch {
	case tok == token.IDENT: return 1
	case tok.IsLiteral(): return 2
	default: return uint32(tok) + 1000
	}
}

func buildSAFast(tokens []uint32) []int {
	n := len(tokens); sa := make([]int, n); rank := make([]int, n)
	for i := range sa { sa[i] = i; rank[i] = int(tokens[i]) }
	iters := 0
	for gap := 1; gap < n; gap *= 2 {
		iters++
		r := make([]int, n); copy(r, rank)
		sort.Slice(sa, func(a, b int) bool {
			pi, pj := sa[a], sa[b]
			if r[pi] != r[pj] { return r[pi] < r[pj] }
			ri, rj := -1, -1
			if pi+gap < n { ri = r[pi+gap] }
			if pj+gap < n { rj = r[pj+gap] }
			return ri < rj
		})
		rank[sa[0]] = 0
		for i := 1; i < n; i++ {
			if r[sa[i]] != r[sa[i-1]] || (sa[i]+gap < n && sa[i-1]+gap < n && r[sa[i]+gap] != r[sa[i-1]+gap]) { rank[sa[i]] = rank[sa[i-1]] + 1 } else { rank[sa[i]] = rank[sa[i-1]] }
		}
		if rank[sa[n-1]] == n-1 { break }
	}
	fmt.Printf("SA iterations: %d\n", iters)
	return sa
}

