	var tokens []uint32
	var files []string
	walkDir2("/usr/local/go/src/cmd", &files, 200)
	for _, f := range files {
		data, _ := os.ReadFile(f)
		fset := token.NewFileSet()
		file := fset.AddFile("", fset.Base(), len(data))
		var s scanner.Scanner; s.Init(file, data, nil, 0)
		for { _, tok, _ := s.Scan(); if tok == token.EOF { break }; if tok != token.COMMENT { tokens = append(tokens, abstract(tok)) } }
		tokens = append(tokens, 0)
	}
	fmt.Printf("Total tokens: %d\n", len(tokens))

	t0 := time.Now()
	sa := buildSAFast(tokens)
	t1 := time.Now()
	fmt.Printf("SA build time: %v (last=%d)\n", t1.Sub(t0), sa[len(sa)-1])
}

func walkDir2(dir string, files *[]string, limit int) {
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		if len(*files) >= limit { return }
		path := dir + "/" + e.Name()
		if e.IsDir() { walkDir2(path, files, limit) } else if len(e.Name()) > 3 && e.Name()[len(e.Name())-3:] == ".go" { *files = append(*files, path) }
	}
