package main

import (
	"fmt"
	"time"
	"sort"
	"os"
	"go/scanner"
	"go/token"
)

func abstract(tok token.Token) uint32 {
	switch {
	case tok == token.IDENT: return 1
	case tok.IsLiteral(): return 2
	case isBinaryOp(tok): return 3
	case isAssignOp(tok): return 4
	case tok == token.INC || tok == token.DEC: return 5
	default: return uint32(tok) + 1000
	}
}
func isBinaryOp(tok token.Token) bool {
	switch tok { case token.ADD, token.SUB, token.MUL, token.QUO, token.REM, token.AND, token.OR, token.XOR, token.SHL, token.SHR, token.AND_NOT, token.LAND, token.LOR, token.EQL, token.LSS, token.GTR, token.NOT, token.NEQ, token.LEQ, token.GEQ: return true }; return false
}
func isAssignOp(tok token.Token) bool {
	switch tok { case token.ADD_ASSIGN, token.SUB_ASSIGN, token.MUL_ASSIGN, token.QUO_ASSIGN, token.REM_ASSIGN, token.AND_ASSIGN, token.OR_ASSIGN, token.XOR_ASSIGN, token.SHL_ASSIGN, token.SHR_ASSIGN, token.AND_NOT_ASSIGN, token.ASSIGN, token.DEFINE: return true }; return false
}

func buildSA(tokens []uint32) []int {
	n := len(tokens); sa := make([]int, n); rank := make([]int, n)
	for i := range sa { sa[i] = i; rank[i] = int(tokens[i]) }
	for gap := 1; gap < n; gap *= 2 {
		r := make([]int, n); copy(r, rank)
		sort.Slice(sa, func(a, b int) bool { pi, pj := sa[a], sa[b]; if r[pi] != r[pj] { return r[pi] < r[pj] }; ri, rj := -1, -1; if pi+gap < n { ri = r[pi+gap] }; if pj+gap < n { rj = r[pj+gap] }; return ri < rj })
		rank[sa[0]] = 0
		for i := 1; i < n; i++ { if r[sa[i]] != r[sa[i-1]] || (sa[i]+gap < n && sa[i-1]+gap < n && r[sa[i]+gap] != r[sa[i-1]+gap]) { rank[sa[i]] = rank[sa[i-1]] + 1 } else { rank[sa[i]] = rank[sa[i-1]] } }
		if rank[sa[n-1]] == n-1 { break }
	}
	return sa
}

func buildLCP(tokens []uint32, sa []int) []int {
	n := len(tokens); lcp := make([]int, n); rank := make([]int, n); for i, s := range sa { rank[s] = i }
	h := 0
	for i := 0; i < n; i++ { if rank[i] > 0 { j := sa[rank[i]-1]; for i+h < n && j+h < n && tokens[i+h] == tokens[j+h] { h++ }; lcp[rank[i]] = h; if h > 0 { h-- } } }
	return lcp
}

type MFI3 struct { Filename string; StartTok, EndTok int; LineOfTok []int }

func main() {
	var files []string
	walkF2("/usr/local/go/src/cmd", &files, 200)
	var allTokens []uint32; var fis []MFI3
	for _, f := range files {
		data, _ := os.ReadFile(f)
		fset := token.NewFileSet()
		file := fset.AddFile("", fset.Base(), len(data))
		var s scanner.Scanner; s.Init(file, data, nil, 0)
		var toks []uint32; var lines []int
		for { pos, tok, _ := s.Scan(); if tok == token.EOF { break }; if tok == token.COMMENT { continue }; toks = append(toks, abstract(tok)); lines = append(lines, fset.Position(pos).Line) }
		startIdx := len(allTokens); allTokens = append(allTokens, toks...); allTokens = append(allTokens, 0)
		fis = append(fis, MFI3{f, startIdx, startIdx+len(toks), lines})
	}
	n := len(allTokens); fmt.Printf("Tokens: %d\n", n)

	sa := buildSA(allTokens); lcp := buildLCP(allTokens, sa)
	posToFI := make([]int, n); for i := range posToFI { posToFI[i] = -1 }
	for fi, info := range fis { for j := info.StartTok; j < info.EndTok; j++ { posToFI[j] = fi } }

	threshold := 200
	type stNode struct { depth, left, right int }; var nodes []stNode
	type stEntry struct { depth, left int }; var stStack []stEntry
	for i := 1; i <= n; i++ {
		l := i - 1; cur := 0; if i < n { cur = lcp[i] }
		for len(stStack) > 0 && stStack[len(stStack)-1].depth > cur {
			top := stStack[len(stStack)-1]; stStack = stStack[:len(stStack)-1]
			if top.depth >= threshold && (i-1) > top.left { nodes = append(nodes, stNode{top.depth, top.left, i-1}) }
			if len(stStack) > 0 && stStack[len(stStack)-1].depth == cur { l = stStack[len(stStack)-1].left; stStack = stStack[:len(stStack)-1] } else { l = top.left }
		}
		if cur > 0 { if len(stStack) == 0 || stStack[len(stStack)-1].depth < cur { stStack = append(stStack, stEntry{cur, l}) } }
	}
	for len(stStack) > 0 { top := stStack[len(stStack)-1]; stStack = stStack[:len(stStack)-1]; if top.depth >= threshold { nodes = append(nodes, stNode{top.depth, top.left, n-1}) } }
	fmt.Printf("Nodes: %d\n", len(nodes))

	// Count total clone pairs for overlap check
	totalPairs := 0; maxRangeSize := 0
	for _, nd := range nodes {
		size := nd.right - nd.left + 1
		if size > maxRangeSize { maxRangeSize = size }
		totalPairs += size * (size - 1) / 2
	}
	fmt.Printf("Total overlap pairs: %d, max range size: %d\n", totalPairs, maxRangeSize)

	// Time just the node processing
	t0 := time.Now()
	totalClonesProcessed := 0
	for _, nd := range nodes {
		for i := nd.left; i <= nd.right; i++ {
			if posToFI[sa[i]] >= 0 { totalClonesProcessed++ }
		}
	}
	t1 := time.Now()
	fmt.Printf("Total clones (before filter): %d (%v)\n", totalClonesProcessed, t1.Sub(t0))
}

func walkF2(dir string, files *[]string, limit int) {
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		if len(*files) >= limit { return }
		path := dir + "/" + e.Name()
		if e.IsDir() { walkF2(path, files, limit) } else if len(e.Name()) > 3 && e.Name()[len(e.Name())-3:] == ".go" { *files = append(*files, path) }
	}
}
