package main

import (
	"fmt"
	"sort"
	"strings"
)

type FileInfo struct {
	Filename  string
	StartTok  int
	EndTok    int
	LineOfTok []int
}

func findClones(tokens []uint32, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)
	if n == 0 {
		return nil
	}
	sa := buildSuffixArray(tokens)
	lcp := buildLCP(tokens, sa)
	return findClonesSimple(tokens, sa, lcp, fileInfos, threshold)
}

func findClonesSimple(tokens []uint32, sa []int, lcp []int, fileInfos []FileInfo, threshold int) []CloneGroup {
	n := len(tokens)

	// Build a fast position-to-fileinfo lookup
	posToFI := make([]int8, n)
	for i := range posToFI {
		posToFI[i] = -1
	}
	for fi, info := range fileInfos {
		if fi > 126 {
			break // int8 max limit
		}
		for j := info.StartTok; j < info.EndTok; j++ {
			posToFI[j] = int8(fi)
		}
	}
	// Fall back to int if more than 127 files
	var posToFILarge []int
	if len(fileInfos) > 127 {
		posToFILarge = make([]int, n)
		for i := range posToFILarge {
			posToFILarge[i] = -1
		}
		for fi, info := range fileInfos {
			for j := info.StartTok; j < info.EndTok; j++ {
				posToFILarge[j] = fi
			}
		}
	}

	getPosToFI := func(pos int) int {
		if posToFILarge != nil {
			return posToFILarge[pos]
		}
		return int(posToFI[pos])
	}

	// Process LCP interval tree nodes
	type stNode struct {
		depth int
		left  int
		right int
	}
	var nodes []stNode

	type stackEntry struct {
		depth int
		left  int
	}
	var stStack []stackEntry

	for i := 1; i <= n; i++ {
		l := i - 1
		currentLCP := 0
		if i < n {
			currentLCP = lcp[i]
		}

		for len(stStack) > 0 && stStack[len(stStack)-1].depth > currentLCP {
			top := stStack[len(stStack)-1]
			stStack = stStack[:len(stStack)-1]

			if top.depth >= threshold && (i-1) > top.left {
				nodes = append(nodes, stNode{
					depth: top.depth,
					left:  top.left,
					right: i - 1,
				})
			}

			if len(stStack) > 0 && stStack[len(stStack)-1].depth == currentLCP {
				l = stStack[len(stStack)-1].left
				stStack = stStack[:len(stStack)-1]
			} else {
				l = top.left
			}
		}

		if currentLCP > 0 {
			if len(stStack) == 0 || stStack[len(stStack)-1].depth < currentLCP {
				stStack = append(stStack, stackEntry{depth: currentLCP, left: l})
			}
		}
	}

	for len(stStack) > 0 {
		top := stStack[len(stStack)-1]
		stStack = stStack[:len(stStack)-1]
		if top.depth >= threshold {
			nodes = append(nodes, stNode{
				depth: top.depth,
				left:  top.left,
				right: n - 1,
			})
		}
	}

	// Process nodes into clone groups
	var cloneGroups []CloneGroup
	seenGroups := make(map[string]bool)

	for _, nd := range nodes {
		var clones []Clone
		for i := nd.left; i <= nd.right; i++ {
			pos := sa[i]
			fi := getPosToFI(pos)
			if fi < 0 {
				continue
			}
			info := fileInfos[fi]
			maxLen := info.EndTok - pos
			length := nd.depth
			if length > maxLen {
				length = maxLen
			}

			startLine := info.LineOfTok[pos-info.StartTok]
			endPos := pos + length - 1
			endLine := info.LineOfTok[endPos-info.StartTok]
			clones = append(clones, Clone{
				Filename:  info.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			})
		}

		if len(clones) < 2 {
			continue
		}

		clones = filterOverlapping(clones)

		if len(clones) < 2 {
			continue
		}

		sortClones(clones)

		key := cloneGroupKey(clones)
		if seenGroups[key] {
			continue
		}
		seenGroups[key] = true

		cloneGroups = append(cloneGroups, CloneGroup{Clones: clones})
	}

	sortCloneGroups(cloneGroups)
	cloneGroups = filterSubsumed(cloneGroups)
	sortCloneGroups(cloneGroups)

	return cloneGroups
}

func posToClone(pos, length int, fileInfos []FileInfo) *Clone {
	for _, fi := range fileInfos {
		if pos >= fi.StartTok && pos < fi.EndTok {
			maxLen := fi.EndTok - pos
			if length > maxLen {
				length = maxLen
			}
			startLine := fi.LineOfTok[pos-fi.StartTok]
			endPos := pos + length - 1
			endLine := fi.LineOfTok[endPos-fi.StartTok]
			return &Clone{
				Filename:  fi.Filename,
				StartLine: startLine,
				EndLine:   endLine,
				StartTok:  pos,
				EndTok:    pos + length,
			}
		}
	}
	return nil
}

// filterOverlapping removes overlapping clones within the same file (O(n log n))
func filterOverlapping(clones []Clone) []Clone {
	if len(clones) <= 1 {
		return clones
	}

	// Group clones by filename
	fileGroups := make(map[string][]int)
	for i, c := range clones {
		fileGroups[c.Filename] = append(fileGroups[c.Filename], i)
	}

	removed := make([]bool, len(clones))

	for _, indices := range fileGroups {
		if len(indices) <= 1 {
			continue
		}
		// Sort by start token within this file
		sort.Slice(indices, func(a, b int) bool {
			return clones[indices[a]].StartTok < clones[indices[b]].StartTok
		})
		// Remove overlapping (keep earlier start, remove later starts that overlap)
		lastEnd := -1
		for _, idx := range indices {
			c := clones[idx]
			if c.StartTok < lastEnd {
				// Overlapping with previous - remove this one
				removed[idx] = true
			} else {
				lastEnd = c.EndTok
			}
		}
	}

	var result []Clone
	for i, c := range clones {
		if !removed[i] {
			result = append(result, c)
		}
	}
	return result
}

func filterSubsumed(groups []CloneGroup) []CloneGroup {
	n := len(groups)
	if n == 0 {
		return nil
	}

	dominated := make([]bool, n)

	for i := 0; i < n; i++ {
		if dominated[i] {
			continue
		}
		gi := groups[i]
		for j := 0; j < n; j++ {
			if i == j || dominated[j] {
				continue
			}
			gj := groups[j]

			if len(gi.Clones) <= len(gj.Clones) {
				if isSubsumedByInjection(gi, gj) {
