		// Sort by start token within this file
		sort.Slice(indices, func(a, b int) bool {
			return clones[indices[a]].StartTok < clones[indices[b]].StartTok
		})
		// Remove overlapping clones (propagate coverage through removed clones)
		maxEnd := -1
		for _, idx := range indices {
